template <typename Mutex>
class std::lock_guard {
public:
    explicit lock_guard(Mutex& m); // Acquires lock
    ~lock_guard(); // Releases lock
private:
    Mutex& m_mutex;
};

code_example:
#include <mutex>
#include <thread>
#include <vector>
#include <iostream>

std::mutex mtx;
int shared_counter = 0;

void increment() {
    std::lock_guard<std::mutex> lock(mtx); // Lock acquired here
    ++shared_counter; // Critical section
    // Lock released automatically when lock goes out of scope
}

int main() {
    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back(increment);
    }
    for (auto& t : threads) {
        t.join();
    }
    std::cout << "Shared counter value: " << shared_counter << std::endl;
    return 0;
}
